    bg=g[0][0]
    # multi-cell components (8-connected)
    seen=[[False]*W for _ in range(H)]; objs=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==bg or seen[r][c]: continue
            col=g[r][c]; st=[(r,c)]; seen[r][c]=True; cells=[]
            while st:
                y,x=st.pop(); cells.append((y,x))
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
            if len(cells)>1: objs.append((cells,col))
    res=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and not any((r,c)==(y,x) for cells_,col_ in [(None,None)] for y,x in cells_: False if True else None):
                pass
    # noise: singleton cells (or small comps) get dominant neighbor color; use mode of existing non-background values in 3x3, preferring colors of large objs
    def mode_cell(r,c):
        cnt=defaultdict(int)
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W: cnt[g[nr][nc]]+=1
        return max(cnt,key=cnt.get)
    marked=set()
    for cs,_ in objs: marked|=set(cs)
    singles=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg and (r,c) not in marked]
    # tie-break: choose color present in a large-object bbox near cell
    out=[row[:] for row in res]
    for r,c in singles:
        best=None
        scores=defaultdict(lambda:-float('inf'))
        for cs,col in objs:
            ys=[y for y,x in cs]; xs=[x for y,x in cs]
            if min(ys)<=r<=max(ys) and min(xs)<=c<=max(xs): scores[col]+=100
        for col in scores:
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    nr,nc=r+dr,c+dc
                    if 0<=nr<H and 0<=nc<W and g[nr][nc]==col: scores[col]+=1
        out[r][c]=max(scores,key=scores.get)
    return out
